// Package store is backplane's PostgreSQL: schema `backplane` (§12.1),
// migrations applied at start, typed queries generated by sqld.
//
// Layout:
//
//	schema.sql     declarative schema: the desired state, every object
//	               qualified with `backplane.`
//	migrations/    history, applied in version order at start (embedded);
//	               `make db-migration name=<what>` writes the next one from
//	               the schema.sql diff
//	queries/       named queries (`-- name: X :one`); `make db` generates db/
//	db/            generated: models and Queries (do not edit)
//
// Every connection runs with search_path=backplane, so sqld's bookkeeping
// table (sqld_migrations) lives in the schema too; the schema itself is
// created before migrating.
package store

import (
	"context"
	"embed"
	"fmt"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/gopherex/pgtx/pkg/tx"
	"github.com/gopherex/xlog"

	"github.com/gopherex/backplane/internal/store/db"
	"github.com/gopherex/backplane/pkg/backplane/deps"
	"github.com/gopherex/backplane/pkg/backplane/infra/postgres"
)

// Schema is where everything of backplane lives in PostgreSQL.
const Schema = "backplane"

//go:embed migrations/*.sql
var migrations embed.FS

// Store is the pool with its transaction manager and the generated queries.
//
// Queries run on DB, which is the transaction in the context when there is
// one and the pool otherwise, so a repository is the same code inside and
// outside of InTx:
//
//	err := st.InTx(ctx, func(ctx context.Context) error {
//	    if err := st.Q.CreateRevision(ctx, ...); err != nil { return err }
//	    return st.Q.SetCurrent(ctx, ...)
//	})
type Store struct {
	// Pool for what the generated queries do not cover (LISTEN, COPY).
	Pool *pgxpool.Pool
	// Trm owns transaction boundaries (pgtx); InTx is the common case.
	Trm tx.Trm
	// DB routes to the context's transaction, else the pool.
	DB tx.DB
	// Q are the generated queries over DB.
	Q *db.Queries
	// Installation identifies the installation this database belongs to.
	Installation    uuid.UUID
	skipAuditExport bool
}

// InTx runs fn in one serializable transaction, retried from scratch on
// serialization failures and deadlocks: fn must be safe to run again.
// Queries through Q and DB inside fn join it; a nested InTx joins it too.
func (s *Store) InTx(ctx context.Context, fn func(ctx context.Context) error) error {
	//nolint:wrapcheck // fn's error as is
	return tx.DoSerializable(ctx, s.Trm, fn, tx.WithRetry(tx.DefaultRetryPolicy))
}

// New is the provider of the store: a required dependency whose start
// connects, creates the schema and applies pending migrations (retried
// with backoff while PostgreSQL is down); its probe pings.
func New(cfg postgres.Config, options ...Option) deps.Provider[*Store] {
	p := provider{cfg: cfg}
	for _, option := range options {
		option(&p)
	}
	return p
}

// Option configures persistence behavior at construction time.
type Option func(*provider)

// AuditExport controls whether new history entries enqueue an export. Existing
// pending exports remain durable and resume when export is enabled again.
func AuditExport(enabled bool) Option { return func(p *provider) { p.skipAuditExport = !enabled } }

type provider struct {
	cfg             postgres.Config
	skipAuditExport bool
}

func (provider) Name() string { return "postgres" }

func (p provider) Provide(ctx context.Context, s deps.Scope) (*Store, error) {
	pg, err := postgres.Open(ctx, s.Log(), p.cfg,
		postgres.Schema(Schema), postgres.Migrations(migrations), postgres.Serializable())
	if err != nil {
		return nil, fmt.Errorf("store: %w", err)
	}

	st, err := open(ctx, pg)
	if err != nil {
		pg.Close()

		return nil, err
	}

	st.skipAuditExport = p.skipAuditExport
	conn := pg.Pool.Config().ConnConfig
	s.Log().Info("postgres ready", xlog.String("host", conn.Host),
		xlog.String("database", conn.Database), xlog.String("installation", st.Installation.String()))

	return st, nil
}

// open wraps a migrated connection and makes sure of the installation.
func open(ctx context.Context, pg *postgres.DB) (*Store, error) {
	st := &Store{Pool: pg.Pool, Trm: pg.Trm, DB: pg.DB, Q: db.New(pg.DB)}

	if err := st.Q.CreateInstallation(ctx); err != nil {
		return nil, fmt.Errorf("store: installation: %w", err)
	}

	inst, err := st.Q.GetInstallation(ctx)
	if err != nil {
		return nil, fmt.Errorf("store: installation: %w", err)
	}

	st.Installation = inst.ID
	if err := st.Q.CreateAuditClock(ctx); err != nil {
		return nil, fmt.Errorf("store: audit clock: %w", err)
	}

	if err := st.Q.CreateLoginState(ctx); err != nil {
		return nil, fmt.Errorf("store: login state: %w", err)
	}

	return st, nil
}

func (provider) Probe(ctx context.Context, s *Store) error {
	if err := s.Pool.Ping(ctx); err != nil {
		return fmt.Errorf("postgres: %w", err)
	}

	return nil
}

func (provider) Close(_ context.Context, s *Store) error {
	s.Pool.Close()

	return nil
}
